<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code.

namespace Tests\Store\Action\Query;

use Module\Store\Action\Dto\StoreShortDto;
use Module\Store\Action\Query\GetStoreListQry;
use Module\Store\Model\Store;
use Module\Store\Model\StoreRepository;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class GetStoreListQryTest extends IntegrationTestCase
{
    private GetStoreListQry $sut;

    private StoreRepository $storeRepository;

    public function setUp(): void
    {
        parent::setUp();

        $this->storeRepository = $this->container->get(StoreRepository::class);

        $this->sut = new GetStoreListQry(
            $this->storeRepository->getEntityManager()
        );
        $this->prepareDb();
    }

    #[Test]
    public function handleReturnsAllStoresOrderedByName(): void
    {
        $result = $this->sut->handle();

        $this->assertEquals(
            [
                new StoreShortDto(21, 'EXT-21', 'Alpha Store'),
                new StoreShortDto(22, 'EXT-22', 'Beta Store'),
                new StoreShortDto(20, 'EXT-20', 'Gamma Store'),
            ],
            $result,
        );
    }

    private function prepareDb(): void
    {
        $this->storeRepository->saveWithId(Store::factory('EXT-20', 'Gamma Store', 'Gamma Address', 20));
        $this->storeRepository->saveWithId(Store::factory('EXT-21', 'Alpha Store', 'Alpha Address', 21));
        $this->storeRepository->saveWithId(Store::factory('EXT-22', 'Beta Store', 'Beta Address', 22));
        $this->storeRepository->flush();
    }
}
